        date: "2018",
        status: "Completed",
        content: `Warning: Violence. Read at your own risk.
        
        "Then? Ano ang isa mo pang plano?" Tanong ni Lizzy ang best friend ko.

"Magpapakamatay na ako, gusto ko ng mamatay dahil hindi ko na kaya ang pang-huhusga nila sa akin dahil ba sa panget ako?"

"Ano bang pinagsasabi mo? Nandito naman ako e, saka pamilya mo nandyan pa!"

"Wala! Basta magpapakamatay na ako, hindi ko na kaya!" Umalis na ako sa kanyang harapan at lumayo na sa kanya.

"Anna wait!" Sigaw niya, alam kong hinahabol niya ko pero hindi ko siya hinintay at pinansin.

Habang naglalakad ako dito sa tulay ay naaalala ko lahat ng mga ginagawa sa akin ng mga nang-aapi sa akin. Hindi ko na napansin ang best friend kong sumusuporta sa akin at dumadamay sa akin dahil na-to-trauma ako.

Dinala na lang ako ng paa ko dito sa isang play ground, kita ko ang mga bata dito ang saya saya, buti pa sila.

Umupo ako sa isang swing at dahan dahang nag-duduyan mag isa.

Habang nakatango ako, ramdam ko na may umupo sa katabi kong swing, akala ko bata. Pero pagka-tingala ko isang lalaki'ng itim ang suot ultimo 'yung sintas ng sapatos niya itim na itim din.

Biglaan na lang ako nanginig nung nagtitigan kaming dalawa. Nakakatakot ang hitsura niya. Gwapo naman pero nakakatakot siya!

"Hi miss!" Kumindat siya sa akin.

Lumapit sya sa akin at saka niya tinanggal ang makapal kong salamin, tinanggal niya ang sanriyo sa buhok ko, ngayon nakaladlad na ako at wala ng salamin.

"Hays! Maganda ka rin naman pala. Ako nga pala si Conan Kon." Husky na boses niya. Nakipagkamay siya sa akin.

"Ako nga pala si Anna Cha." Inabot ko na ang kamay niya.

"Pwede ka ba sumama sa akin?" Biglaan niyang tanong na ikinagulat ko naman, "hindi ako masama ni hindi ako nang-ho-holdap. Sadyang ito lang ang suot ko, favorite ko kasi ang black e," kamot ulo pa siya, "pwede ka ba sumama sa akin?" Inilapit niya ang kamay niya sa akin at humawak na ako Sa kanyang kamay.

Naglakad kaming dalawa papunta sa labas ng play ground na ito, hindi kami halos nag-usap habang naglalakd kami palabas rito.

"Gusto mo ba libre kita?" Cool niyang pagkakatanong at titig na titih siya sa akin ako naman hindi makatingin.

"A-am h-hindi b-ba n-nakakah-hi-y-ya?" Nauutal kong tanong, ngumisi siya sa akin.

"Oo naman! 'Wag ka ng mahiya. Andito lang naman ako e." Para akong kinikilig sa sinasabi niya.

Nilibre lang niya ako ng sampung pisong kikiam at sampung pisong fishball saka sampung pisong chocolate palamig. Ganun din ang binili niya.

Habang naglalakad kami nagulat na lang ako sa sinabi niya, "mukhang may problema ka Anna? Sabihin mo nga sa'kin."

"Ammm.. Ayaw ko nahihiya ako!"

"Sige na! Huwag ka ng mahiya. Andito lang ako." Sht yan nanaman! Bat ako kinikilig kapag sinasabi sa akin ng mga lalaki 'yan?

"Ammm, naglayas ako.."

"Ayun lang?! Ano bang dahilan?"

"Ammm, kasi.. Kaya ako naglayas k-kasiiii.. Ammm," kita ko siya na nakakunot ang noo at pilit hinihintay ang sasagutin ko, "h-hindi k-ko na nakakaya ang pang-aapi nila sa akin. Kaya ako naglayas. Ayaw ko na! Hindi ko na kaya! Kaya naisip kong mag-layas at magpakamatay na." Nakatitig pa din siya sa akin.

"Ahh ganon ba. Alam mo, huwah kang magpakamatay. Alam kong malulutas mo din 'yang problemang 'yan! Kaya kung ako sa'yo umuwi ka na. Pero gabi na delikado. hindi ko kakayanin na mayroong mangyaring masama sa'yo. Doon ka muna tumuloy sa condo ko." ano ba 'yan! Kinikilig ako kapag sinasabi niya 'yan! Hindi ko na napipigilan. Lalo akong nahuhulog!

Nagulat na lang ako ng bigla niyang hawakan ang ulo ko ng dahan dahan. "Huwag mo nga kong hawakan sa ulo." Medyo pabebe kong sabi.

"Bat kinikilig ka?"

"Kinikilig ako kapag ginaganyan ako e. Saka sa'yo kinikilig din ako sa'yo. Ang cool mo kasi e. Para kang bad boy! Gwapo pa!" Ngumisi na lang siya sa akin at hindi na nagsalita. Diretso na lang kami ng lakad.

Ngayon, nandito na kami sa condo niya. Napakaluwag neto at color white ang pader. Walang halos gamit. Mayroong gym room dito.

"Ito damit mo!" Inabutan niya ako ng damit at agad ko naman ito kinuha. Hindi ko alam kung bakit mayroon siyang pambabaeng damit.

"Tulog ka na!" Huling sabi niya sa akin at lumabas na siya dito sa kwarto na inilagay sa akin.

Kinuha ko ang unan at niyakap ko ito, iniimagine ko na si Conan, pinagpapantasyahan ko siya kunwari niyayakap ko siya na nakahubad. Ang landi ko! Hahahaha!

**

Nagising na lang ako sa sinag ng araw. Pagkamulat ko nakabukas ang kurtina mula sa harap ko kaya kitang-kita ang view at sobrang liwanag.

Nag-ayos na ako bago ako lumabas.

Pagkalabas ko nadatnan ko na lang nakahubad si Conan. Ang laki ng katawan niya at may abs. Napakagwapo niya kapag walang cover ang buong katawan. Parang Jeydon! Ako yata ang Candice ngayong araw at siya si Jeydon.

"Oh! Kain na beautiful lady."

Inusog niya 'yung upuan at pinaupo niya ako. Ang almusal namin ngayon kape, pandesal saka sinangag at itlog. Simple lang.

Pagkatapos naming kumain ay lumabas kami ng condo niya, sabi niya kasi ipapasyal lang niya ako.

Maganda ang condo na ito, pinasyal niya ako sa garden ng condominium.

Pinasyal niya ako sa buong condominium at lahat ay magaganda, sobang ganda, I sure kapag nakapunta ka dito ay hindi ka na uuwi pa.

"Uuwi ka na ba?" Tanong niya.

"H-hindi pa."

"Mabuti." May nilabas siya mula sa likod niya. "Ngayon? Papatayin na kita! Gusto mo na mamatay diba?"

"Ano pinagsasabi mo?!"

"Dahil ako si.." Tinanggal niya ang kanyang mukha. Wait? Mukha? Which means, maskara lang ang mukha na 'yon?! "Jobbie ako ang nangbubully at nang-aapi sa'yo simula noon pa!" Napatitig ako sa kanya ng ilang minuto bago ako umiyak.

"Sige na! Patayin mo na ako! bwisit na mundong 'to! Hindi ko na kaya! Ayaw ko na. Soge na patayin mo na ako. Huwag mo na akong pahirapan!" Tinutukan na niya ako ng baril. "KILL ME IN YOUR WAY! KILL ME!" Sigaw ko.

Hindi ko na alm ang nangyayari ngayon, ang alam ko na lang nabaril na niya ako. Matutupad na ang hiling ko.. Ang mamahinga pada hindi na ako mahirapan. Hindi ko inakala na si Conan at Jobbie ay iisa.`
