        content: `Trigger Warning: Sensitive, violence and heavy story. Read at your own risk.
        
        “Dalian mo na at magbihis ka na riyan kasi pupunta na tayo sa sementeryo para sa Papa mo,” tawag ni Mama mula sa labas ng kwarto ko.

Birthday ngayon ni Papa. Agad nga akong nagmadaling mag-ayos at mag-make up dahil doon. Pagkalabas ko ng aking kwarto, sinalubong ako ni Mama at ng dalawa kong nakatatandang kapatid.

Pagdating naman namin sa sementeryo, nagsalita si Mama, “Miss na miss ko na ‘yung Papa ninyo. Kung nabubuhay pa sana siya, edi sana buo pa rin tayong masayang pamilya.”

Napalunok ako sa sinabi ni Mama.

“Siguro kaya hindi pa rin ako maka-move on sa Papa ninyo, kasi hindi pa rin nahuhuli ‘yung pumatay sa kanya,” dagdag pa niya.

“Deserve niya lang po iyon,” sagot ko nang mahina dahilan para agad akong lingunin ni Mama.

“Ano’ng sabi mo?” tanong niya na may halong inis.

Napatingin lang ako sa kanya at hindi ako agad nakasagot. Narinig niya pala ako. Sa oras na ‘yon, tila bumalik sa akin lahat ng alaala—ang sakit, ang galit, at ang mga pangyayaring kailanman ay hindi ko makakalimutan.

Anak ako ni Mama sa iba. Ni-rape siya ng katrabaho niya. Namatay ang tunay kong Ama na masama dahil nanlaban daw siya sa mga pulis at binaril. Simula noon, naging masaya at tahimik na ang buhay nina Mama, Papa, at mga kapatid ko.

Pero hindi ako naging masaya at tahimik.

Palagi akong binubungangaan ni Papa. Kasalanan ko raw kung bakit matagal na-depress si Mama, dahil hindi niya ako matanggap kasi ako raw nagpapaalala ng masamang nangyari sa kanya. Nang mamatay ang tunay kong Ama, saka lang niya ako tinanggap, pero si Papa? Hindi kailanman.

Bukod sa masasakit na sinasabi sa akin ni Papa ay palihim din niya akong sinasaktan lalo na kapag nakatalikod si Mama o siya’y wala. Hanggang sa naging teenager ako ay palagi niya pa rin akong pinagmamalupitan, hanggang isang gabi, palihim rin niya akong pinapalayas.

“Maawa po kayo, Papa. Huwag n’yo naman po akong paalisin. Ibalik n’yo na po ako sa bahay. Hindi ko po kayang mawalay sa inyo,” pagmamakaawa ko sa kanya.

Pero kinaladkad niya ako paalis. Gusto niya talaga akong mapalayas. “Hindi naman kita anak kaya deserve mong umalis. Isa kang malas, Trisha!”

“Hindi po ako malas! Mahal po ako ni Mama!” sigaw ko, punong-puno na ng galit at hinanakit. “Buong buhay ko tiniis ko ang pananakit n’yo sa akin, Papa. Hindi ko isinumbong kina Mama kahit kailan, pero ngayon, hindi ko na kaya. Hindi ako papayag na palayasin ninyo ako. Isusumbong ko kayo kay Mama!”

Inis na inis nga ang mukha ni Papa sa akin at nilapitan niya nga ako. Nung nalapitan niya ako ay tinulak ko si Papa ngunit sa hindi ko inaasahan ay nagulat ako dahil tumilapon siya sa kalsada. Nasagasaan siya ng isang kotse! Nanlaki ang mga mata ko, hindi ko alam ang gagawin. Hanggang sa lumabas ang lalaki mula sa kotse.

“Hala… Napatay ko yata siya,” takot na takot niyang sabi. Kinuha niya ang cellphone niya, mukhang tatawag ng emergency. Pero bigla akong lumapit.

“Wait lang po…”

“Teka, sino ka? Anak ka ba ng nasagasaan ko? Please, huwag mo akong ipakulong,” nagmamakaawa siya. “Natatakot ako.”

“Hindi naman po ako magsusumbong…” sagot ko, pero nagsimula akong kabahan nang tignan niya ako. Kaya umalis ako sa harapan niya at nagsimulang tumakbo. Naramdaman kong hinahabol niya ako!

“Saglit lang! Bumalik ka rito!” sigaw nga ng lalaki.

Lumingon ako sa kanya habang tumatakbo. “Huwag mo po akong saktan! Hindi po ako magsusumbong!” sigaw ko habang tumatakbo.

Sa malayong pagtakbo ko at pagliko ko ay umabot na kami sa sa tulay na may maraming sasakyan. Nakaramdam ako ng pagod ngunit tumakbo pa rin ako. Dito na nga niya ako nahabol at nahawakan niya pa ang braso ko.

“Hindi ka pwedeng makawala! Hindi ako papayag na ipakulong mo ako! Sumama ka sa akin!” sigaw niya. Nakakatakot ang boses niya, marahas ang pagkakahawak niya.

“Hindi ko po kayo isusumbong! Hayaan n’yo na po akong makaalis. Wala rin pong kwenta ang Ama kong ‘yon. Palagi niya lang akong sinasaktan. Deserve niyang mamatay!”

“Hindi ako naniniwala sa’yo!” bulalas niya, at mas marahas niya akong hinila.

Wala akong matakbuhan. Wala ring makakatulong sa akin dahil nasa tulay kami at mabilis din ang takbo ng mga sasakyan. Pinilit kong kumawala, at sa lakas ng pagkakabig ko, nahulog siya sa tulay. Sa tubig siya bumagsak!

Nanlaki ang mga mata ko at nagtingin sa buong paligid ngunit dire-diretso lang ang takbo ng mga sasakyan. Tumakbo ako palayo, nagpatuloy ako sa pagtakbo hanggang sa makalayo ako.

Mabuti na lang at wala nang nangyaring masama sa akin matapos ang ang mga araw na ‘yan. Wala ring nagduda sa akin nang inimbestigahan ng pulis ang pagkamatay ng Ama ko.

Hindi ako ang pumatay sa Ama ko dahil iba ang may kasalanan no'n, iyon ay ang lalaking naihulog ko sa tulay ang may kasalanan dahil siya ang nakasagasa sa Papa ko at siya ang dahilan ng lahat.

Ngunit tama lang din ang nangyari sa Ama ko. Deserve niya iyon. Sinaktan niya ako habang buhay siya. Kaya ngayong patay na siya ay hindi na niya ako kailanman masasaktan!

“Trisha?”

Nabigla ako sa tawag ni Mama. Bumalik ako sa aking ulirat.

Ngumiti ako. “Ang ibig ko pong sabihin, Ma, deserve lang po ni Papa na mabigyan ng hustisya. Sana nahuli na lang ‘yung pumatay sa kanya. Pero matagal na po ‘yon, Ma. Wala na tayong magagawa. Ang mahalaga, masaya tayo ngayon, at alam kong nakikita niya tayong buo.”

Ngumiti rin si Mama. “Tama ka, Anak. Ganoon na nga lang ang iisipin natin. Mahal mo rin talaga ang Papa mo ano? Alam ko naman na itinuring ka niyang tunay na Anak at ikinatutuwa ko ‘yon.”

Ngumiti rin ako pabalik kay Mama. “Nagpapaiyak naman kayo eh! Yakap nga po!” Nagkatawanan kami ni Mama habang umiiyak at saka ko siya niyakap. Nakisali rin ang mga kapatid ko.

Tumingin nga ako sa puntod ni Papa at saka ako ngumisi. Matapos ang yakapan namin ay pinakinggan ko na lang ang mga kwento ni Mama kay Papa. Pagkatapos niyan ay umuwi na kami.

Inaamin ko na oo, inuusig pa rin ako ng konsensya ko dahil masama rin ang lihim ko ngunit kinukumbinsi rin ako ng sarili ko na hindi dapat ako makaramdam ng ganiyan dahil mas masama ang nagawa sa akin ng Ama ko. Hindi ako kriminal at wala akong kasalanan dahil hindi ko naman siya pinatay. Ngunit ang lihim kong may alam ako sa tunay na nangyari sa kanya ay itatago ko na lang hanggang sa aking hukay at kahit pa hanggang sa judgement.

Ito ang kwento kong may lihim din na hindi nabubunyag dahil ang totoo, deserve din ng Papa ko ang mamatay.`
